mapper.select:
SELECT COUNT(DISTINCT t.user_id) FROM (
    SELECT user_id FROM consultation_session
    WHERE deleted_flag = 0 AND create_time >= #{since}
    UNION
    SELECT user_id FROM emotion_diary
    WHERE deleted_flag = 0 AND create_time >= #{since}
) t

SELECT DATE_FORMAT(t.d, '%Y-%m-%d') AS date, COUNT(DISTINCT t.user_id) AS cnt
FROM (
    SELECT DATE(create_time) AS d, user_id FROM consultation_session
    WHERE deleted_flag = 0 AND create_time >= #{start}
    UNION
    SELECT DATE(create_time) AS d, user_id FROM emotion_diary
    WHERE deleted_flag = 0 AND create_time >= #{start}
) t
GROUP BY DATE_FORMAT(t.d, '%Y-%m-%d')
ORDER BY date
